import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.CHeM0PsO.js";const l="/images/misskey-lists.webp",r="/images/misskey-antennas.webp",m=JSON.parse('{"title":"列表与天线","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/lists-antennas.md","filePath":"guide/misskey/lists-antennas.md","lastUpdated":1793076233000}'),n={name:"guide/misskey/lists-antennas.md"};function d(o,t,h,p,c,u){return e(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="列表与天线" tabindex="-1">列表与天线 <a class="header-anchor" href="#列表与天线" aria-label="Permalink to &quot;列表与天线&quot;">​</a></h1><p>列表和天线是两种定制信息流的工具：列表按<strong>人</strong>组织，天线按<strong>关键词</strong>组织。</p><h2 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to &quot;列表&quot;">​</a></h2><p>列表（Lists）是你自建的用户分组。把感兴趣的用户加入同一个列表，即可只看他们（以及可选的「包含回复」）的帖子。</p><ul><li>通过侧栏「列表」创建，例如「好友」「画师」「新闻源」。</li><li>列表时间线可以在<a href="/guide/posts#时间线">时间线</a>中切换查看。</li><li>列表是私有的，只有你自己能看到列表内容和成员。</li><li>列表上限和每个列表的成员数上限由服务器策略决定。</li></ul><p><img src="'+l+'" alt="列表管理"></p><h2 id="天线" tabindex="-1">天线 <a class="header-anchor" href="#天线" aria-label="Permalink to &quot;天线&quot;">​</a></h2><p>天线（Antennas）按条件自动聚合帖子，比如「追踪包含某个关键词的所有新帖」。</p><ul><li>通过侧栏「天线」创建，每个天线有独立时间线。</li><li>天线数量上限由服务器策略决定。</li><li>可设置的条件：</li></ul><table tabindex="0"><thead><tr><th>条件</th><th>说明</th></tr></thead><tbody><tr><td>接收来源</td><td>所有帖子 / 已关注用户的帖子 / 来自指定用户 / 来自指定列表 / 过滤指定用户后的所有帖子</td></tr><tr><td>包含关键字</td><td>空格分隔为 AND，换行分隔为 OR</td></tr><tr><td>排除关键字</td><td>规则同上，命中则不收录</td></tr><tr><td>其他</td><td>区分大小写、排除机器人账户、包含回复、仅带有附件的帖子、排除敏感频道的帖子</td></tr></tbody></table><ul><li>适合持续追踪特定话题、角色名或活动标签。</li></ul><p><img src="'+r+'" alt="天线管理"></p><h2 id="列表-vs-天线怎么选" tabindex="-1">列表 vs 天线怎么选 <a class="header-anchor" href="#列表-vs-天线怎么选" aria-label="Permalink to &quot;列表 vs 天线怎么选&quot;">​</a></h2><ul><li>想持续看<strong>某些人</strong>的动态 → 用列表。</li><li>想追踪<strong>某类内容</strong>（无论谁发的）→ 用天线。</li></ul>',14)])])}const g=a(n,[["render",d]]);export{m as __pageData,g as default};
